INSERT INTO products (slug, name, category, description, price_cents) VALUES
('ethiopia-guji', 'Αιθιοπία Γκούτζι', 'beans', 'Washed επεξεργασία, ψήσιμο για φίλτρο, 250 γρ. Νότες γιασεμιού, βερίκοκου και μπεργκαμόντου. Καθαρός, ανθικός και φωτεινός.', 1450),
